import placeholders from "./artPlaceholders.json";

/**
 * Blurred stand-in of a painting while it loads (roadmap item 64), generated by
 * `npm run art:placeholders`. Spread into next/image:
 *   <Image src={art} {...artPlaceholder(art)} … />
 * Unknown pictures (icons, remote images) get no placeholder.
 */
export function artPlaceholder(src: string | undefined): { placeholder?: "blur"; blurDataURL?: string } {
  const data = src ? (placeholders as Record<string, string>)[src] : undefined;
  return data ? { placeholder: "blur", blurDataURL: data } : {};
}
